using System;using System.Collections.Generic;using System.Linq;using UnityEngine;
namespace LostRealmsOW {
 [DefaultExecutionOrder(20000)] public sealed class OpenWorldInteriorResidentAnchor:MonoBehaviour {void LateUpdate(){var npc=GetComponent<OpenWorldNPC>();if(npc&&npc.Visual)npc.Visual.transform.localPosition=Vector3.down*.19f;}}
 public sealed class OpenWorldTownInteriors:MonoBehaviour {
  Transform built;float next;public static readonly List<Vector3> Residents=new List<Vector3>();public static readonly List<Vector3> Chests=new List<Vector3>();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){new GameObject("Town interiors").AddComponent<OpenWorldTownInteriors>();}
  void Update(){var gm=OpenWorldManager.I?OpenWorldManager.I:FindAnyObjectByType<OpenWorldManager>();if(!gm||!gm.Hero||!gm.WorldRoot||gm.WorldRoot==built||Time.time<next)return;next=Time.time+2;var architecture=GameObject.Find("Architecture & Cliffs");if(!architecture)return;built=gm.WorldRoot;Residents.Clear();Chests.Clear();
   var houses=architecture.transform.Cast<Transform>().Where(t=>new Vector2(t.position.x,t.position.z).magnitude<85&&(t.name.ToLowerInvariant().Contains("house")||t.name.ToLowerInvariant().Contains("armory")||t.name.ToLowerInvariant().Contains("tavern"))).OrderBy(t=>t.name).ThenBy(t=>t.position.x).ToArray();
   int chosenCaches=0;
   foreach(var house in houses){var b=OpenWorldMaterialHelper.ComputeRendererBounds(house);var spots=FindFloors(house,b);bool hall=house.name.ToLowerInvariant().Contains("armory")||house.name.ToLowerInvariant().Contains("tavern");if(hall){int added=0;foreach(var spot in spots){if(Residents.Any(p=>(p-spot).sqrMagnitude<5)||house.GetComponentsInChildren<Transform>().Any(t=>t.name.ToLowerInvariant().Contains("door")&&Vector2.Distance(new Vector2(t.position.x,t.position.z),new Vector2(spot.x,spot.z))<1.8f))continue;var npc=OpenWorldNPC.Spawn("interior-resident-"+Residents.Count,added==0?"Guild Steward":"Guild Artisan","Guild Resident","Welcome inside. Take a moment to rest before the next journey.",0,-1,spot,spot,built);npc.transform.position=spot-Vector3.up*.05f;npc.gameObject.AddComponent<OpenWorldInteriorResidentAnchor>();var body=npc.gameObject.AddComponent<CapsuleCollider>();body.height=1.8f;body.radius=.3f;body.center=Vector3.up*.9f;gm.NPCs.Add(npc);Residents.Add(npc.transform.position);if(++added>=2)break;}}
    else if(chosenCaches<4&&spots.Count>0){chosenCaches++;int hash=0;foreach(char c in house.name)hash=unchecked(hash*31+c);var spot=spots[(hash&int.MaxValue)%spots.Count];string id="chest:interior:"+house.name+":"+Mathf.RoundToInt(house.position.x)+":"+Mathf.RoundToInt(house.position.z);if(gm.CollectedWorldIds.Contains(id))continue;var chest=OpenWorldCollectible.Spawn(OWCollectibleKind.SecretChest,spot,built,1,"HOUSEHOLD CACHE",id);chest.transform.position=spot-Vector3.up*.04f;gm.Collectibles.Add(chest);Chests.Add(chest.transform.position);}
   }Debug.Log("[Interiors] validated residents="+Residents.Count+" chests="+Chests.Count);
  }
  static bool Enclosed(Transform house,Vector3 foot){bool old=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;try{return new[]{Vector3.left,Vector3.right,Vector3.forward,Vector3.back}.All(dir=>Physics.RaycastAll(foot+Vector3.up*.7f,dir,18,~0,QueryTriggerInteraction.Ignore).Any(h=>h.transform.IsChildOf(house)));}finally{Physics.queriesHitBackfaces=old;}}
  public static List<Vector3> FindFloors(Transform house,Bounds b){var spots=new List<Vector3>();for(float x=b.min.x+.8f;x<b.max.x-.8f;x+=1.1f)for(float z=b.min.z+.8f;z<b.max.z-.8f;z+=1.1f){var origin=new Vector3(x,b.min.y+2.8f,z);foreach(var hit in Physics.RaycastAll(origin,Vector3.down,3.5f,~0,QueryTriggerInteraction.Ignore).OrderByDescending(h=>h.point.y)){if(!hit.transform.IsChildOf(house)||hit.normal.y<.8f)continue;Vector3 foot=hit.point+Vector3.up*.06f;bool roof=Physics.RaycastAll(foot+Vector3.up*.2f,Vector3.up,7,~0,QueryTriggerInteraction.Ignore).Any(h=>h.transform.IsChildOf(house)&&h.distance>1.7f);if(!roof||!Enclosed(house,foot))continue;if(Physics.CheckCapsule(foot+Vector3.up*.36f,foot+Vector3.up*1.48f,.33f,~0,QueryTriggerInteraction.Ignore))continue;spots.Add(foot);break;}}return spots;}
 }
}
